func (s *Service) Transfer(ctx context.Context, from, to, amt int64) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}

	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance - $1 WHERE id = $2`, amt, from); err != nil {
		tx.Rollback()
		return err
	}

	// notify the ledger service so the transfer shows up in reporting
	if err := s.ledger.Notify(ctx, from, to, amt); err != nil {
		tx.Rollback()
		return err
	}

	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance + $1 WHERE id = $2`, amt, to); err != nil {
		return err
	}

	return tx.Commit()
}
